#!/bin/bash
# land-medical-atmosphere.sh — The Medical Hub breathes amber.
#
# The owner's amber-steam reference applied to the whole Medical hub: a drawn
# plume and smoked-glass hero on the landing, a quieter amber sky behind all
# ten work pages, cards floating as white paper, every contrast measured off
# composited pixels and the arithmetic written down as a test.
#
# WEB ONLY. No backend, no migration — push and Vercel takes it.
#
# Run from the repo root:  bash land-medical-atmosphere.sh
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

# ── PRECONDITION ──────────────────────────────────────────────────────────
# Captured log + case, NOT `git log | grep -q` — under pipefail that pipe is
# a SIGPIPE race that reports the commit missing precisely when you are
# standing on it. land-cv-profile.sh carries the full autopsy.
LOG="$(git log --oneline -40)"
MARK="A career is a list, so store it as one"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\", which is not in the last 40 commits."
     echo "   Run land-cv-profile.sh first (or pull main)."; exit 1 ;;
esac
NEEDS="The Medical Hub breathes amber"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
# Untracked landing artifacts are not dirty work — the script is running from
# the repo root, where its predecessors and their patches still sit.
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

# ── the patch, one line of base64 ─────────────────────────────────────────
# One line on purpose: macOS LibreSSL's `openssl base64 -d -A` silently
# produces an EMPTY file from wrapped input. The sha256 is the only thing
# between a truncated download and a half-applied patch.
PATCH="$(mktemp "${TMPDIR:-/tmp}/matmos.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="328934d8cce8e862b390eab833219fb7f4225ca02ab1530ccd77e38e320c98f0"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified ($(wc -c < "$PATCH" | tr -d ' ') bytes)"

git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
echo "== applies cleanly"

git am --keep-cr -C1 < "$PATCH"
echo "== committed"

# ── gates ─────────────────────────────────────────────────────────────────
echo
echo "== together-city-react"
cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS"
echo
echo " Web only — push and Vercel ships it. Nothing to run on Railway."
echo
echo " What changed: /medical arrives through amber weather with a drawn"
echo " steam plume and a smoked-glass hero; all ten inner medical pages sit"
echo " on a quieter amber sky with their cards floating as white paper."
echo " Every contrast was measured off composited pixels and the arithmetic"
echo " now lives in src/app/the-atmosphere-holds-its-ink.test.ts."
echo "==============================================================="
